<template><section class="ds-page"><header class="ds-header"><div><span>MCP 管理 / Python模板</span><h1>Python 模板管理</h1><p>这里只展示已发布的稳定能力；开发中的 .py 文件不会被 Agent 检索。</p></div><button @click="load">刷新</button></header>
  <div class="ds-template-toolbar"><input v-model="query" type="search" placeholder="按场景、功能或关键词进行混合检索"><button class="ds-primary" @click="search">BM25 + KNN 检索</button><span>{{ templates.length }} 个模板</span></div><p v-if="error" class="ds-alert error">{{ error }}</p><p v-if="message" class="ds-alert success">{{ message }}</p>
  <div v-if="loading" class="ds-empty">正在加载 Python 模板…</div><div v-else-if="!templates.length" class="ds-empty"><strong>暂无 Python 模板</strong><p>数据科学人员成功测试并发布脚本后，模板会出现在这里。</p></div>
  <div v-else class="ds-table-wrap"><table><thead><tr><th>模板名称</th><th>场景描述</th><th>发布人</th><th>版本</th><th>MCP 同步</th><th>索引</th><th>Runtime</th><th>状态</th><th>发布时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in templates" :key="item.id"><td><strong>{{ item.templateName }}</strong><small>{{ item.toolName }}</small></td><td class="ds-scenario">{{ item.scenario }}</td><td>{{ item.ownerId }}</td><td>{{ item.version }}</td><td><span :class="['ds-status',statusClass(item.mcpSyncStatus)]" :title="item.mcpSyncMessage">{{ item.mcpSyncStatus }}</span></td><td><span :class="['ds-status',statusClass(item.indexStatus)]">{{ item.indexStatus }}</span></td><td><span :class="['ds-status',statusClass(item.runtimeStatus)]">{{ item.runtimeStatus }}</span></td><td>{{ item.status }}</td><td>{{ formatTime(item.publishedAt) }}</td><td><button @click="openDetail(item)">查看</button><button @click="test(item)">测试执行</button><button @click="toggle(item)">{{ item.status==='PUBLISHED'?'禁用':'重新索引并启用' }}</button></td></tr></tbody></table></div>
  <div v-if="hits.length" class="ds-search-results"><h2>混合检索结果</h2><article v-for="hit in hits" :key="hit.templateId"><strong>{{ hit.templateName }}</strong><span>{{ hit.channel }} · {{ Number(hit.score).toFixed(4) }}</span><p>{{ hit.scenario }}</p></article></div>
  <div v-if="active" class="ds-modal" @mousedown.self="active=null"><section class="ds-detail"><h2>{{ active.templateName }}</h2><p>{{ active.scenario }}</p><dl><div><dt>功能</dt><dd>{{ active.description }}</dd></div><div><dt>关键词</dt><dd>{{ active.keywords||'-' }}</dd></div><div><dt>Asset / Script</dt><dd>{{ active.assetId }} / {{ active.scriptId }}</dd></div><div><dt>输入 Schema</dt><dd><pre>{{ pretty(active.inputSchemaJson) }}</pre></dd></div><div><dt>输出 Schema</dt><dd><pre>{{ pretty(active.outputSchemaJson) }}</pre></dd></div></dl><footer><button @click="active=null">关闭</button></footer></section></div>
</section></template>
<script src="../js/views/PythonTemplatesView.js"></script><style src="../styles/pages/data-science.css"></style>
